def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform row separates the marker pattern from the data pattern.
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            if r < h - 1:
                markers, data = grid[:r], grid[r + 1:]
            else:
                markers, data = grid[:r], []
            if len(markers) == len(data) and data:
                return [
                    [
                        0 if data[i][j] == 0 or markers[i][j] == 0 else 2
                        for j in range(w)
                    ]
                    for i in range(len(data))
                ]

    # A uniform column separates the two patterns.
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            if c < w - 1:
                markers = [row[:c] for row in grid]
                data = [row[c + 1:] for row in grid]
            else:
                markers, data = [], []
            if markers and len(markers[0]) == len(data[0]):
                return [
                    [
                        0 if data[i][j] == 0 or markers[i][j] == 0 else 2
                        for j in range(len(data[i]))
                    ]
                    for i in range(h)
                ]

    return grid
